for (const [language, messages] of Object.entries(advancedMessages)) Object.assign(interfaceText[language], messages);
for (const [language, [check, done, ready]] of Object.entries(genericStatusMessages)) {
  Object.assign(interfaceText[language], { 'Check the values and try again.': check, 'Done.': done, 'Ready.': ready });
}
for (const [language, ui] of Object.entries(interfaceText)) Object.assign(advancedToolLocales[language].ui, ui);
